ruleBookInfo.init:
@js:(function(){
  var html=String(result);
  var doc=Packages.org.jsoup.Jsoup.parse(html);
  function lab(key){
    var items=doc.select('div.detail-item');
    for(var i=0;i<items.size();i++){
      var it=items.get(i);
      var k=String(it.select('strong.label-width').text()).replace(/[：:\s]/g,'');
      if(k===key) return String(it.select('span.detail-content').text()).trim();
    }
    return '';
  }
  var name=lab('名称');
  if(!name){
    var t=String(doc.title());
    var m=t.match(/《([^》]+)》/);
    if(m) name=m[1];
  }
  var title=lab('标题');
  var cat=lab('分类');
  var tags=lab('类别');
  var date=lab('日期');
  var dur=lab('时长');
  // 简介：站点无正文简介，用 meta description 去掉模板话术
  var intro='';
  var md=doc.select('meta[name=description]').first();
  if(md!==null){
    intro=String(md.attr('content')).trim();
    intro=intro.replace(/^[\s\S]*?详情介绍[：:]/,'').replace(/[，,]?好看的[\s\S]*?推荐。?$/,'').trim();
  }
  // 简介首句常与书名/标题重复，去重后再拼
  var seen={};
  function uniq(x){
    var t=String(x||'').trim();
    if(!t) return '';
    var k=t.replace(/[\s【】《》\[\]()（）_]/g,'');
    if(k.length<2||seen[k]) return '';
    seen[k]=1;
    return t;
  }
  var bits=[];
  var t1=uniq(title);
  if(t1) bits.push(t1);
  var t2=uniq(intro);
  if(t2) bits.push(t2);
  if(cat) bits.push('分类：'+cat);
  if(tags) bits.push('标签：'+tags.replace(/\s+/g,' / '));
  if(dur) bits.push('时长：'+dur);
  if(date) bits.push('更新：'+date);
  var fullIntro=bits.join('\n');
  // 封面
  var cover='';
  var im=doc.select('div.stui-vodlist__box img').first();
  if(im!==null){
    cover=String(im.attr('data-original')).trim();
    if(!cover) cover=String(im.attr('src')).trim();
    if(cover.indexOf('load.gif')>=0) cover='';
  }
  // 分类（kind 走 getStringList，用纯 text 值避免复杂拼接）
  var kindParts=[];
  var kseen={};
  function kadd(x){
    var t=String(x||'').trim();
    if(!t||kseen[t]) return;
    kseen[t]=1;
    kindParts.push(t);
  }
  kadd(cat);
  if(tags){
    var arr=tags.split(/\s+/);
    for(var k=0;k<arr.length;k++){ kadd(arr[k]); }
  }
  var out={
    n:name,
    a:'',
    k:kindParts.join(','),
    i:fullIntro,
    c:cover,
    l:'',
    w:dur||'',
    t:''
  };
  return JSON.stringify(out);
})()

